import java.util.*;class Solution{public String decodeString(String s){Deque<Integer>nums=new ArrayDeque<>();Deque<StringBuilder>prev=new ArrayDeque<>();StringBuilder cur=new StringBuilder();int n=0;for(char c:s.toCharArray()){if(Character.isDigit(c))n=n*10+c-'0';else if(c=='['){nums.push(n);prev.push(cur);cur=new StringBuilder();n=0;}else if(c==']'){String x=cur.toString();cur=prev.pop();int k=nums.pop();while(k-->0)cur.append(x);}else cur.append(c);}return cur.toString();}}
